  `sales` int NOT NULL DEFAULT '0' COMMENT '销量',
  `cover_image` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '封面图片URL',
  `category_id` bigint DEFAULT NULL COMMENT '类别ID（外键）',
  `merchant_id` bigint DEFAULT NULL COMMENT '商家ID（外键）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：0下架，1上架',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除标记',
  `audit_status` int DEFAULT NULL COMMENT '审核状态：0待审核，1审核通过，2审核拒绝',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` text COLLATE utf8mb4_unicode_ci COMMENT '审核备注（拒绝原因等）',
  `audit_user_id` bigint DEFAULT NULL COMMENT '审核人ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `isbn` (`isbn`),
  KEY `idx_book_name` (`book_name`),
  KEY `idx_author` (`author`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_merchant_id` (`merchant_id`),
  KEY `idx_status` (`status`),
  KEY `idx_sales` (`sales`),
  CONSTRAINT `fk_book_category` FOREIGN KEY (`category_id`) REFERENCES `category` (`id`),
  CONSTRAINT `fk_book_merchant` FOREIGN KEY (`merchant_id`) REFERENCES `sys_user` (`id`)
