--
-- Table structure for table `order_item`
--

DROP TABLE IF EXISTS `order_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单明细ID',
  `order_id` bigint NOT NULL COMMENT '订单ID（外键）',
  `book_id` bigint NOT NULL COMMENT '图书ID（外键）',
  `book_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '图书名称（冗余字段，提高查询效率）',
  `author` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '作者（冗余字段）',
  `cover_image` text COLLATE utf8mb4_unicode_ci COMMENT '封面图片（冗余字段）',
  `price` decimal(10,2) NOT NULL COMMENT '购买时的单价',
  `quantity` int NOT NULL COMMENT '购买数量',
  `subtotal` decimal(10,2) NOT NULL COMMENT '小计金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除标记',
  `merchant_id` bigint DEFAULT NULL,
  `merchant_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `merchant_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '待发货' COMMENT '商品状态：待发货/待收货/已收货',
  `refund_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '退款状态：待处理/已通过/已拒绝',
  `refund_id` bigint DEFAULT NULL COMMENT '关联的退款申请ID',
  `express_company` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '快递公司',
  `express_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '快递单号',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_book_id` (`book_id`),
  CONSTRAINT `fk_orderitem_book` FOREIGN KEY (`book_id`) REFERENCES `book` (`id`),
  CONSTRAINT `fk_orderitem_order` FOREIGN KEY (`order_id`) REFERENCES `order_info` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=244 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单明细表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `order_item`
--

