/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `refund_request` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `refund_reason` varchar(50) NOT NULL,
  `refund_description` varchar(500) DEFAULT NULL,
  `refund_amount` decimal(10,2) NOT NULL,
  `refund_status` varchar(20) NOT NULL DEFAULT 'pending',
  `merchant_reply` varchar(500) DEFAULT NULL,
  `process_time` datetime DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `merchant_id` bigint DEFAULT NULL COMMENT '商家ID，对应订单项所属商家',
  `order_item_id` bigint DEFAULT NULL COMMENT '订单项ID，对应退款商品',
  `merchant_name` varchar(100) DEFAULT NULL COMMENT '商家名称',
  `original_status` varchar(50) DEFAULT NULL COMMENT '原订单状态（用于退款被拒绝时恢复）',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_refund_status` (`refund_status`)
) ENGINE=InnoDB AUTO_INCREMENT=116 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

